/* eslint-disable no-undef */
/**
 * Kyreo service worker.
 *
 * Deliberately small and hand-written rather than generated by @serwist/next or
 * next-pwa. Those plugins hook the bundler, and Next 16 builds with Turbopack,
 * for which Serwist's integration is a separate and less-travelled path. They
 * also assume a server build, not `output: "export"`.
 *
 * The scope here is genuinely narrow, which is what makes hand-writing it safe:
 * this worker caches STATIC ASSETS ONLY. Firestore data is already persisted by
 * the SDK's own IndexedDB cache (see lib/firebase.ts), so the worker must never
 * touch API traffic — intercepting it would fight the SDK and risk serving stale
 * clinical records.
 *
 * The precache manifest and build id placeholders below are substituted by
 * scripts/build-sw.mjs. Do not reference those token names anywhere else in this
 * file — the build script substitutes every occurrence.
 */

const BUILD_ID = "__BUILD_ID__";
const CACHE_NAME = `kyreo-static-${BUILD_ID}`;
const PRECACHE = __PRECACHE_MANIFEST__;
const OFFLINE_URL = "/offline/";

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // Individually, not addAll: one 404 must not abort the whole install and
      // leave the app with no worker at all.
      await Promise.all(
        PRECACHE.map(async (url) => {
          try {
            await cache.add(new Request(url, { cache: "reload" }));
          } catch {
            // Non-fatal; the asset will be fetched from the network on demand.
          }
        }),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // The cache name carries the build id, so a new deploy gets a new cache and
      // every old one is dropped. No per-file revision bookkeeping needed.
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith("kyreo-static-") && name !== CACHE_NAME)
          .map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

/** Static assets are content-hashed by Next, so they are safe to serve cache-first. */
function isPrecacheable(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/icons/") ||
    url.pathname === "/manifest.webmanifest" ||
    url.pathname === "/favicon.ico"
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Never intercept anything but same-origin GETs. This is what keeps Firestore,
  // Firebase Auth and Cloud Storage traffic entirely out of the worker.
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Navigations: network first so a deploy is picked up immediately, falling back
  // to the cached shell and finally to the offline page.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(request);
          const cache = await caches.open(CACHE_NAME);
          cache.put(request, fresh.clone());
          return fresh;
        } catch {
          const cached =
            (await caches.match(request, { ignoreSearch: true })) ??
            (await caches.match(OFFLINE_URL));
          return (
            cached ??
            new Response("Sin conexión", {
              status: 503,
              headers: { "Content-Type": "text/plain; charset=utf-8" },
            })
          );
        }
      })(),
    );
    return;
  }

  if (!isPrecacheable(url)) return;

  // Immutable, content-hashed assets: cache first.
  event.respondWith(
    (async () => {
      const cached = await caches.match(request);
      if (cached) return cached;
      const response = await fetch(request);
      if (response.ok) {
        const cache = await caches.open(CACHE_NAME);
        cache.put(request, response.clone());
      }
      return response;
    })(),
  );
});
